<script>
  import { createEventDispatcher } from 'svelte';
  import { projectsApi, categoriesApi } from '../services/database.js';
  import { authStore, uiStore } from '../stores/index.js';

  const dispatch = createEventDispatcher();
  
  let projectName = '';
  let projectDescription = '';
  let isCreating = false;
  let currentUser = null;

  authStore.subscribe(state => {
    currentUser = state.user;
  });
  
  async function handleSubmit() {
    // 验证
    if (!projectName.trim()) {
      uiStore.showNotification('请输入项目名称', 'error');
      return;
    }
    
    if (!currentUser?.id) {
      uiStore.showNotification('用户信息缺失', 'error');
      return;
    }
    
    isCreating = true;
    uiStore.showLoading('创建项目中...');
    try {
      // 创建项目
      const result = await projectsApi.create(
        projectName.trim(),
        projectDescription.trim(),
        currentUser.id
      );
      
      if (result.error) {
        throw result.error;
      }
      
      uiStore.showNotification('项目创建成功', 'success');
      uiStore.closeModal();
      
      // 重置表单
      projectName = '';
      projectDescription = '';
      
      // 通知父组件刷新
      dispatch('created');
      
    } catch (error) {
      console.error('Create project error:', error);
      uiStore.showNotification('创建失败: ' + (error.message || '未知错误'), 'error');
    } finally {
      isCreating = false;
      uiStore.hideLoading();
    }
  }

  function handleCancel() {
    uiStore.closeModal();
  }
</script>

<form on:submit|preventDefault={handleSubmit}>
  <div class="form-group">
    <label for="project-name">项目名称 *</label>
    <input
      id="project-name"
      type="text"
      bind:value={projectName}
      placeholder="请输入项目名称"
      disabled={isCreating}
      required
      autofocus
    />
  </div>

  <div class="form-group">
    <label for="project-desc">项目描述</label>
    <textarea
      id="project-desc"
      bind:value={projectDescription}
      placeholder="请输入项目描述（可选）"
      disabled={isCreating}
      rows="3"
    ></textarea>
  </div>

  <div class="form-info">
    <p>💡 创建项目后：</p>
    <ul>
      <li>项目将出现在左侧导航栏</li>
      <li>可以在项目下创建材料分类（如：木材、管子、钢板等）</li>
      <li>每个分类下可以录入材料的入库、出库记录</li>
    </ul>
  </div>

  <div class="form-actions">
    <button type="submit" class="btn-primary" disabled={isCreating}>
      {isCreating ? '创建中...' : '创建项目'}
    </button>
    <button 
      type="button" 
      class="btn-secondary" 
      on:click={handleCancel}
      disabled={isCreating}
    >
      取消
    </button>
  </div>
</form>

