<script>
  import Router from 'svelte-spa-router';
  import { onMount } from 'svelte';
  import { auth } from './providers/index.js';
  import { config } from './config.js';
  import { authStore, uiStore } from './stores/index.js';
  import Login from './Login.svelte';
  import MainLayout from './layouts/MainLayout.svelte';
  import GlobalLoading from './components/GlobalLoading.svelte';
  import Notification from './components/Notification.svelte';
  import './global.css';

  // Routes
  import Dashboard from './views/Dashboard.svelte';
  import MaterialList from './views/MaterialList.svelte';
  import UserManagement from './views/UserManagement.svelte';

  const routes = {
    '/': Dashboard,
    '/project/:projectId/:viewType': MaterialList,
    '/project/:projectId/:viewType/:categoryId': MaterialList,
    '/users': UserManagement,
    '*': Dashboard
  };

  // 使用 authStore 的状态来控制渲染，确保认证完全就绪后才渲染 MainLayout
  let authState = { user: null, role: null, isLoading: true, isSuperAdmin: false };
  authStore.subscribe(state => {
    authState = state;
  });

  // 计算属性：是否已认证
  $: isAuthenticated = !!authState.user;
  $: isLoading = authState.isLoading;

  onMount(async () => {
    // 确保 authStore 处于 loading 状态
    authStore.setLoading(true);
    
    try {
      // Check for session
      const { data: { session } } = await auth.getSession();
      if (session?.user) {
        // Check if this is the super admin by email pattern
        const isSuperAdminUser = session.user.email?.endsWith('@bmms.superadmin.local');
        
        if (isSuperAdminUser) {
          authStore.setUser(session.user, 'super_admin', true);
        } else {
          // Get real role from users table
          const { getUserRole } = await import('./services/userRole.js');
          const userRole = await getUserRole(session.user.id);
          authStore.setUser(session.user, userRole, false);
        }
      } else {
        // 没有 session，设置为未登录状态
        authStore.clearUser();
      }
    } catch (error) {
      console.error('Failed to get session:', error);
      authStore.clearUser();
    }

    // Listen for auth state changes
    const subscription = auth.onAuthStateChange(async (event, user) => {
      if (user) {
        const isSuperAdminUser = user.email?.endsWith('@bmms.superadmin.local');
        
        if (isSuperAdminUser) {
          authStore.setUser(user, 'super_admin', true);
        } else {
          // Get real role from users table
          const { getUserRole } = await import('./services/userRole.js');
          const userRole = await getUserRole(user.id);
          authStore.setUser(user, userRole, false);
        }
      } else {
        authStore.clearUser();
      }
    });

    return () => subscription.unsubscribe();
  });

  async function handleLoginSuccess(user, loginIsSuperAdmin = false) {
    if (loginIsSuperAdmin) {
      authStore.setUser(user, 'super_admin', true);
    } else {
      // Get real role from users table
      const { getUserRole } = await import('./services/userRole.js');
      const userRole = await getUserRole(user.id);
      authStore.setUser(user, userRole, false);
    }
  }

  async function handleLogout() {
    // Clear session
    await auth.signOut();
    authStore.clearUser();
    // 强制跳转到首页（不带任何路由参数）
    window.location.replace('/');
  }
</script>

<GlobalLoading />
<Notification />

<main>
  {#if isLoading}
    <div class="loading-container">
      <div class="spinner"></div>
      <p>加载中...</p>
    </div>
  {:else if isAuthenticated}
    <MainLayout on:logout={handleLogout}>
      <Router {routes} />
    </MainLayout>
  {:else}
    <Login 
      onLoginSuccess={handleLoginSuccess} 
    />
  {/if}
</main>

<style>
  :global(*, *::before, *::after) {
    box-sizing: border-box;
  }

  :global(body) {
    margin: 0;
    padding: 0;
    font-family: 'Segoe UI', 'PingFang SC', 'Microsoft YaHei', sans-serif;
    background-color: #f0f2f5;
    color: #333;
  }

  main {
    min-height: 100vh;
  }

  .loading-container {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    min-height: 100vh;
    background: linear-gradient(135deg, #1a365d 0%, #2d4a7c 100%);
    color: white;
  }

  .spinner {
    width: 48px;
    height: 48px;
    border: 4px solid rgba(255, 255, 255, 0.3);
    border-top: 4px solid white;
    border-radius: 50%;
    animation: spin 1s linear infinite;
    margin-bottom: 16px;
  }

  @keyframes spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
  }
</style>