<script>
  import { createEventDispatcher } from 'svelte';
  import { push } from 'svelte-spa-router';
  import { projectStore, authStore, uiStore } from '../stores/index.js';
  import { canCreateProject as checkCanCreateProject, isAdmin as checkIsAdmin } from '../constants/roles.js';
  import { categoriesApi } from '../services/database.js';

  export let collapsed = false;

  const dispatch = createEventDispatcher();

  let projects = [];
  let selectedProjectId = null;
  let selectedViewType = null;
  let selectedCategoryId = null;
  let expandedProjects = {};
  let expandedViews = {};
  let role = null;

  // Rename category state
  let showRenameModal = false;
  let renamingCategory = null;
  let newCategoryName = '';

  // Fixed Level 2 menu items
  const viewTypes = [
    { id: 'inbound', label: '入库材料汇总', icon: '📥' },
    { id: 'outbound', label: '出库材料汇总', icon: '📤' },
    { id: 'remaining', label: '剩余材料汇总', icon: '📊' }
  ];

  projectStore.subscribe(state => {
    projects = state.projects;
    selectedProjectId = state.selectedProjectId;
    selectedViewType = state.selectedViewType;
    selectedCategoryId = state.selectedCategoryId;
    
    // 自动展开选中的项目和视图
    if (selectedProjectId) {
      expandedProjects[selectedProjectId] = true;
      expandedProjects = expandedProjects;
      
      if (selectedViewType) {
        const viewKey = `${selectedProjectId}-${selectedViewType}`;
        expandedViews[viewKey] = true;
        expandedViews = expandedViews;
      }
    }
  });

  authStore.subscribe(state => {
    role = state.role;
  });

  function toggleProject(projectId) {
    expandedProjects[projectId] = !expandedProjects[projectId];
    expandedProjects = expandedProjects;
  }

  function toggleView(projectId, viewType) {
    const key = `${projectId}-${viewType}`;
    expandedViews[key] = !expandedViews[key];
    expandedViews = expandedViews;
  }

  function selectView(projectId, viewType, categoryId = null) {
    projectStore.selectView(projectId, viewType, categoryId);
    if (categoryId) {
      push(`/project/${projectId}/${viewType}/${categoryId}`);
    } else {
      push(`/project/${projectId}/${viewType}`);
    }
  }

  function handleCreateProject() {
    dispatch('createProject');
  }

  function canCreateProject() {
    return checkCanCreateProject(role);
  }

  function isAdmin() {
    return checkIsAdmin(role);
  }

  // Rename category functions
  function openRenameModal(e, category) {
    e.stopPropagation();
    renamingCategory = category;
    newCategoryName = category.name;
    showRenameModal = true;
  }

  function closeRenameModal() {
    showRenameModal = false;
    renamingCategory = null;
    newCategoryName = '';
  }

  async function handleRenameCategory() {
    if (!newCategoryName.trim()) {
      uiStore.showNotification('请输入分类名称', 'error');
      return;
    }

    if (newCategoryName.trim() === renamingCategory.name) {
      uiStore.showNotification('名称未修改', 'warning');
      return;
    }

    uiStore.showLoading('重命名中...');
    try {
      const result = await categoriesApi.update(renamingCategory.$id, {
        name: newCategoryName.trim()
      });
      
      if (result.error) throw result.error;

      uiStore.showNotification('重命名成功', 'success');
      closeRenameModal();
      
      // Reload to update sidebar
      window.location.reload();
    } catch (error) {
      console.error('Rename category error:', error);
      const errorMsg = error?.message || '重命名失败';
      uiStore.showNotification(errorMsg, 'error');
    } finally {
      uiStore.hideLoading();
    }
  }
</script>

<nav class="sidebar-nav" class:collapsed>
  {#if canCreateProject() && !collapsed}
    <button class="create-project-btn" on:click={handleCreateProject}>
      <span class="icon">+</span>
      <span class="text">新建项目</span>
    </button>
  {/if}

  <div class="tree-container">
    {#each projects as project (project.$id)}
      <div class="tree-item project-item">
        <button 
          class="tree-node" 
          class:expanded={expandedProjects[project.$id]}
          on:click={() => toggleProject(project.$id)}
        >
          <span class="expand-icon">{expandedProjects[project.$id] ? '▼' : '▶'}</span>
          <span class="node-icon">📁</span>
          {#if !collapsed}
            <span class="node-label">{project.name}</span>
          {/if}
        </button>

        {#if expandedProjects[project.$id] && !collapsed}
          <div class="tree-children">
            {#each viewTypes as view}
              {@const viewKey = `${project.$id}-${view.id}`}
              <div class="tree-item view-item">
                <button 
                  class="tree-node level-2"
                  class:active={selectedProjectId === project.$id && selectedViewType === view.id && !selectedCategoryId}
                  class:expanded={expandedViews[viewKey]}
                  on:click={() => {
                    toggleView(project.$id, view.id);
                    selectView(project.$id, view.id);
                  }}
                >
                  <span class="expand-icon">
                    {#if project.categories?.length > 0}
                      {expandedViews[viewKey] ? '▼' : '▶'}
                    {:else}
                      <span class="spacer"></span>
                    {/if}
                  </span>
                  <span class="node-icon">{view.icon}</span>
                  <span class="node-label">{view.label}</span>
                </button>

                {#if expandedViews[viewKey] && project.categories?.length > 0}
                  <div class="tree-children">
                    {#each project.categories as category (category.$id)}
                      <div class="category-node-wrapper">
                        <button 
                          class="tree-node level-3"
                          class:active={selectedCategoryId === category.$id && selectedViewType === view.id}
                          on:click={() => selectView(project.$id, view.id, category.$id)}
                        >
                          <span class="spacer"></span>
                          <span class="node-icon">📋</span>
                          <span class="node-label">{category.name}</span>
                        </button>
                        {#if isAdmin()}
                          <button 
                            class="rename-btn"
                            on:click={(e) => openRenameModal(e, category)}
                            title="重命名"
                          >
                            ✏️
                          </button>
                        {/if}
                      </div>
                    {/each}
                  </div>
                {/if}
              </div>
            {/each}
          </div>
        {/if}
      </div>
    {/each}

    {#if projects.length === 0 && !collapsed}
      <div class="empty-state">
        <p>暂无项目</p>
        {#if canCreateProject()}
          <button class="create-first-btn" on:click={handleCreateProject}>
            创建第一个项目
          </button>
        {/if}
      </div>
    {/if}
  </div>
</nav>

<!-- Rename Category Modal -->
{#if showRenameModal}
  <div class="modal-overlay" on:click={closeRenameModal} on:keydown={(e) => e.key === 'Escape' && closeRenameModal()} role="button" tabindex="-1">
    <div class="modal" on:click|stopPropagation>
      <div class="modal-header">
        <h3>重命名分类</h3>
        <button class="close-btn" on:click={closeRenameModal}>×</button>
      </div>
      <div class="modal-body">
        <div class="form-group">
          <label>分类名称</label>
          <input 
            type="text" 
            bind:value={newCategoryName} 
            placeholder="请输入新的分类名称"
          />
        </div>
        <div class="form-actions">
          <button class="btn btn-primary" on:click={handleRenameCategory}>保存</button>
          <button class="btn btn-secondary" on:click={closeRenameModal}>取消</button>
        </div>
      </div>
    </div>
  </div>
{/if}

